var n=`0653-afra`;var r=`world-0653`;var a=`GM`;var t=`western-africa`;var s=4;var o=90;var g={en:`Afra`,ua:`Афра`};var l={en:`Afra is a Gambia classic prepared with lamb, ginger root, garlic, lemon juice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Афра, страва кухні країни Гамбія зі складниками: ягнятина, корінь імбиру, часник, лимонний сік. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 60 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 60 хвилин.`,t:[`marinating`],m:60,i:[[`lamb`,650,`g`],[`ginger-root`,25,`g`],[`garlic`,4,`clove`],[`lemon-juice`,35,`ml`],[`ground-cumin`,5,`g`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:10,i:[[`red-bell-pepper`,210,`g`],[`yellow-onion`,180,`g`]]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[[`sunflower-oil`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon`,1,`pcs`]]}];var u={slug:n,id:r,country:`GM`,region:t,servings:4,minutes:90,title:g,text:l,steps:m};export{a as country,u as default,r as id,o as minutes,t as region,s as servings,n as slug,m as steps,l as text,g as title};